(2)		B.　SELECT NAME, SALARY FROM EMP WHERE DEPT_ID = 10101 AND DEPT_ID = 10102;
(3)		C.　SELECT NAME, SALARY FROM EMP WHERE DEPT_ID LIKE '1%';
